from __future__ import annotations

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException

from src.api.deps import get_analysis_service
from src.api.schemas.analysis import (
    AnalysisCatalogOut,
    AnalysisFacetIn,
    AnalysisFacetOut,
    AnalysisFilterIn,
    AnalysisMetricReferenceIn,
    AnalysisQueryIn,
    AnalysisQueryOut,
    AnalysisRowOut,
    AnalysisSortIn,
)
from src.manual_qc.analysis.analysis_service import (
    AnalysisQueryService,
    AnalysisValidationError,
)
from src.manual_qc.analysis.models import (
    AnalysisFilter,
    AnalysisPage,
    AnalysisQuery,
    AnalysisScope,
    AnalysisSort,
    MetricReference,
)


router = APIRouter(prefix="/api/manual-qc/analysis", tags=["manual-qc-analysis"])
AnalysisService = Annotated[AnalysisQueryService, Depends(get_analysis_service)]

# HTTP 使用 camelCase，与其余 API 字段一致；领域层使用 Python 的 snake_case。
# `parameters` 是自由键字典，Pydantic 的 alias generator 不会自动递归转换它，
# 所以必须在这个唯一的边界显式归一化，不能让 Repository 或前端各自猜测。
_PARAMETER_KEY_ALIASES = {
    "questionLabel": "question_label",
    "questionOption": "question_option",
}


def _metric_reference(value: AnalysisMetricReferenceIn) -> MetricReference:
    return MetricReference(
        id=value.id,
        parameters={
            _PARAMETER_KEY_ALIASES.get(key, key): parameter_value
            for key, parameter_value in value.parameters.items()
        },
    )


def _scope(value: AnalysisQueryIn | AnalysisFacetIn) -> AnalysisScope:
    scope = value.scope
    return AnalysisScope(
        date_start=scope.date_start,
        date_end=scope.date_end,
        project_names=tuple(scope.project_names),
        task_names=tuple(scope.task_names),
        group_names=tuple(scope.group_names),
        employee_ids=tuple(scope.employee_ids),
    )


def _filter(value: AnalysisFilterIn) -> AnalysisFilter:
    return AnalysisFilter(
        target=_metric_reference(value.target),
        operator=value.operator,
        value=value.value,
    )


def _sort(value: AnalysisSortIn) -> AnalysisSort:
    return AnalysisSort(
        target=_metric_reference(value.target),
        direction=value.direction,
    )


@router.get("/catalog", response_model=AnalysisCatalogOut)
def catalog(service: AnalysisService) -> AnalysisCatalogOut:
    return AnalysisCatalogOut.model_validate(service.catalog())


@router.post("/query", response_model=AnalysisQueryOut)
def query(
    payload: AnalysisQueryIn,
    service: AnalysisService,
) -> AnalysisQueryOut:
    domain_query = AnalysisQuery(
        source_id=payload.source_id,
        scope=_scope(payload),
        group_by=tuple(payload.group_by),
        measures=tuple(_metric_reference(item) for item in payload.measures),
        filters=tuple(_filter(item) for item in payload.filters),
        sort=tuple(_sort(item) for item in payload.sort),
        page=AnalysisPage(number=payload.page.number, size=payload.page.size),
    )
    try:
        result = service.query(domain_query)
    except AnalysisValidationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return AnalysisQueryOut(
        source_id=result.source_id,
        group_by=list(result.group_by),
        rows=[
            AnalysisRowOut(
                key=row.key,
                dimensions=row.dimensions,
                measures=row.measures,
                computed_at=row.computed_at,
            )
            for row in result.rows
        ],
        total=result.total,
        page=payload.page,
        computed_at=result.computed_at,
        warnings=list(result.warnings),
    )


@router.post("/facets", response_model=AnalysisFacetOut)
def facets(
    payload: AnalysisFacetIn,
    service: AnalysisService,
) -> AnalysisFacetOut:
    try:
        values = service.facets(
            source_id=payload.source_id,
            scope=_scope(payload),
            dimension_id=payload.dimension_id,
            question_label=payload.question_label,
        )
    except AnalysisValidationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return AnalysisFacetOut(dimension_id=payload.dimension_id, values=values)

import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnSizingState,
  ExpandedState,
  FilterFn,
  SortingState,
  VisibilityState,
} from '@tanstack/vue-table'

export interface WorkbenchViewState {
  sorting: SortingState
  expanded: ExpandedState
  columnVisibility: VisibilityState
  columnOrder: ColumnOrderState
  columnSizing: ColumnSizingState
  columnFilters: ColumnFiltersState
}

export interface ColumnEditorSpec<TData> {
  type: 'text' | 'number' | 'select'
  options?: string[]
  canEdit?: (row: TData) => boolean
}

export interface WorkbenchFilterSpec {
  type: 'text' | 'select' | 'text-select' | 'date-range' | 'number-range'
  options?: string[]
}

export interface WorkbenchTextSelectionFilterValue {
  query: string
  selected: string[]
}

export interface WorkbenchColumnControl {
  id: string
  label: string
  visible: boolean
  canMoveLeft: boolean
  canMoveRight: boolean
}

export interface WorkbenchAnalysisRequest<TData> {
  rows: TData[]
  filterSummary: string
  filters: ColumnFiltersState
}

export const multiSelectFilter: FilterFn<unknown> = (
  row,
  columnId,
  filterValue,
) => {
  const selected = String(filterValue ?? '')
    .split('\u0000')
    .filter(Boolean)
  return selected.length === 0 || selected.includes(String(row.getValue(columnId) ?? ''))
}

export function parseTextSelectionFilter(
  value: unknown,
): WorkbenchTextSelectionFilterValue {
  if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
    const candidate = value as Partial<WorkbenchTextSelectionFilterValue>
    return {
      query: typeof candidate.query === 'string' ? candidate.query : '',
      selected: Array.isArray(candidate.selected)
        ? candidate.selected.filter(
            (item): item is string => typeof item === 'string',
          )
        : [],
    }
  }
  return {
    query: '',
    selected: String(value ?? '').split('\u0000').filter(Boolean),
  }
}

export const textSelectionFilter: FilterFn<unknown> = (
  row,
  columnId,
  filterValue,
) => {
  const { query, selected } = parseTextSelectionFilter(filterValue)
  const value = String(row.getValue(columnId) ?? '')
  const matchesText =
    !query.trim() ||
    value.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())
  const matchesSelection = selected.length === 0 || selected.includes(value)
  return matchesText && matchesSelection
}

export const dateRangeFilter: FilterFn<unknown> = (
  row,
  columnId,
  filterValue,
) => {
  const [start = '', end = ''] = String(filterValue ?? '').split('\u0000')
  const value = String(row.getValue(columnId) ?? '')
  if (!value) return false
  return (!start || value >= start) && (!end || value <= end)
}

export const numberRangeFilter: FilterFn<unknown> = (
  row,
  columnId,
  filterValue,
) => {
  const [minimum = '', maximum = ''] = String(filterValue ?? '').split('\u0000')
  const rawValue = row.getValue(columnId)
  if (rawValue == null || rawValue === '') return false
  const value = Number(rawValue)
  if (!Number.isFinite(value)) return false
  const lowerBound = minimum === '' ? null : Number(minimum)
  const upperBound = maximum === '' ? null : Number(maximum)
  return (
    (lowerBound == null || value >= lowerBound) &&
    (upperBound == null || value <= upperBound)
  )
}

declare module '@tanstack/vue-table' {
  interface ColumnMeta<TData, TValue> {
    filter?: WorkbenchFilterSpec
  }
}

import type { AnalysisMetric } from '../analysis/types/analysis'
import type { SnapshotRow } from '../types/snapshot'
import type {
  DashboardMetricBlock,
  DashboardMetricCard,
  DashboardMetricReference,
  DashboardMetricResult,
  DashboardMetricValueResult,
  LegacyDashboardMetricCard,
  LegacyDashboardMetricId,
} from '@/shared/dashboard/types'

interface ResultTotals {
  annotationTotal: number
  annotationSubmitted: number
  goodSubmitted: number
  badSubmitted: number
  goodExpectedAllocated: number
  badExpectedAllocated: number
  goodAllocated: number
  badAllocated: number
  goodCompleted: number
  badCompleted: number
  goodPassed: number
  badPassed: number
  goodRejected: number
  badRejected: number
}

const FALLBACK_LABELS: Record<string, string> = {
  'annotation.total': '标注总量',
  'annotation.submitted': '标注提交量',
  'annotation.good_submitted': 'Good 提交量',
  'annotation.bad_submitted': 'Bad 提交量',
  'annotation.good_rate': 'Good 占比',
  'annotation.bad_rate': 'Bad 占比',
  'acceptance.expected_allocated': '预期验收分配量',
  'acceptance.allocated': '实际验收分配量',
  'acceptance.allocation_coverage_rate': '分配覆盖率',
  'acceptance.allocation_fulfillment_rate': '分配达成率',
  'acceptance.completed': '验收完成量',
  'acceptance.pending': '验收未完成量',
  'acceptance.completion_rate': '验收完成率',
  'acceptance.passed': '验收通过量',
  'acceptance.rejected': '验收打回量',
  'acceptance.pass_rate': '验收通过率',
  'acceptance.reject_rate': '验收打回率',
  'good.acceptance.allocated': 'Good 验收分配量',
  'good.acceptance.completed': 'Good 验收完成量',
  'good.acceptance.completion_rate': 'Good 验收完成率',
  'good.acceptance.passed': 'Good 验收通过量',
  'good.acceptance.rejected': 'Good 验收打回量',
  'good.acceptance.pass_rate': 'Good 验收通过率',
  'bad.acceptance.allocated': 'Bad 验收分配量',
  'bad.acceptance.completed': 'Bad 验收完成量',
  'bad.acceptance.completion_rate': 'Bad 验收完成率',
  'bad.acceptance.passed': 'Bad 验收通过量',
  'bad.acceptance.rejected': 'Bad 验收打回量',
  'bad.acceptance.pass_rate': 'Bad 验收通过率',
}

function cloneConfig<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T
}

function emptyTotals(): ResultTotals {
  return {
    annotationTotal: 0,
    annotationSubmitted: 0,
    goodSubmitted: 0,
    badSubmitted: 0,
    goodExpectedAllocated: 0,
    badExpectedAllocated: 0,
    goodAllocated: 0,
    badAllocated: 0,
    goodCompleted: 0,
    badCompleted: 0,
    goodPassed: 0,
    badPassed: 0,
    goodRejected: 0,
    badRejected: 0,
  }
}

function addRow(total: ResultTotals, row: SnapshotRow): void {
  total.annotationTotal += row.annotation_total
  total.annotationSubmitted += row.annotation_submitted
  total.goodSubmitted += row.good_metrics.annotation_submitted
  total.badSubmitted += row.bad_metrics.annotation_submitted
  total.goodExpectedAllocated += row.good_metrics.expect_alloc
  total.badExpectedAllocated += row.bad_metrics.expect_alloc
  total.goodAllocated += row.good_metrics.actual_alloc
  total.badAllocated += row.bad_metrics.actual_alloc
  total.goodCompleted += row.good_metrics.actual_complete
  total.badCompleted += row.bad_metrics.actual_complete
  total.goodPassed += row.good_metrics.actual_pass
  total.badPassed += row.bad_metrics.actual_pass
  total.goodRejected += row.good_metrics.actual_reject
  total.badRejected += row.bad_metrics.actual_reject
}

function ratio(numerator: number, denominator: number): number | null {
  return denominator ? numerator / denominator * 100 : null
}

function metricValue(metricId: string, total: ResultTotals): number | null {
  const allocated = total.goodAllocated + total.badAllocated
  const expectedAllocated =
    total.goodExpectedAllocated + total.badExpectedAllocated
  const completed = total.goodCompleted + total.badCompleted
  const passed = total.goodPassed + total.badPassed
  const rejected = total.goodRejected + total.badRejected
  const values: Record<string, number | null> = {
    'annotation.total': total.annotationTotal,
    'annotation.submitted': total.annotationSubmitted,
    'annotation.good_submitted': total.goodSubmitted,
    'annotation.bad_submitted': total.badSubmitted,
    'annotation.good_rate': ratio(
      total.goodSubmitted,
      total.annotationSubmitted,
    ),
    'annotation.bad_rate': ratio(
      total.badSubmitted,
      total.annotationSubmitted,
    ),
    'acceptance.expected_allocated': expectedAllocated,
    'acceptance.allocated': allocated,
    'acceptance.allocation_coverage_rate': ratio(
      allocated,
      total.annotationSubmitted,
    ),
    'acceptance.allocation_fulfillment_rate': ratio(
      allocated,
      expectedAllocated,
    ),
    'acceptance.completed': completed,
    'acceptance.pending': Math.max(0, allocated - completed),
    'acceptance.completion_rate': ratio(completed, allocated),
    'acceptance.passed': passed,
    'acceptance.rejected': rejected,
    'acceptance.pass_rate': ratio(passed, completed),
    'acceptance.reject_rate': ratio(rejected, completed),
    'good.acceptance.allocated': total.goodAllocated,
    'good.acceptance.completed': total.goodCompleted,
    'good.acceptance.completion_rate': ratio(
      total.goodCompleted,
      total.goodAllocated,
    ),
    'good.acceptance.passed': total.goodPassed,
    'good.acceptance.rejected': total.goodRejected,
    'good.acceptance.pass_rate': ratio(
      total.goodPassed,
      total.goodCompleted,
    ),
    'bad.acceptance.allocated': total.badAllocated,
    'bad.acceptance.completed': total.badCompleted,
    'bad.acceptance.completion_rate': ratio(
      total.badCompleted,
      total.badAllocated,
    ),
    'bad.acceptance.passed': total.badPassed,
    'bad.acceptance.rejected': total.badRejected,
    'bad.acceptance.pass_rate': ratio(
      total.badPassed,
      total.badCompleted,
    ),
  }
  return values[metricId] ?? null
}

function metricUnit(
  metricId: string,
  catalog: AnalysisMetric[],
): 'count' | 'percent' {
  return (
    catalog.find((metric) => metric.id === metricId)?.unit ??
    (metricId.endsWith('_rate') ? 'percent' : 'count')
  )
}

function formatMetric(value: number | null, unit: 'count' | 'percent'): string {
  if (value == null) return '—'
  return unit === 'percent'
    ? `${value.toFixed(1)}%`
    : Math.round(value).toLocaleString('zh-CN')
}

function resolveValue(
  reference: DashboardMetricReference,
  total: ResultTotals,
  catalog: AnalysisMetric[],
  labelOverride?: string,
): DashboardMetricValueResult {
  const unit = metricUnit(reference.id, catalog)
  const value = metricValue(reference.id, total)
  return {
    metricId: reference.id,
    label:
      labelOverride ||
      catalog.find((metric) => metric.id === reference.id)?.label ||
      FALLBACK_LABELS[reference.id] ||
      reference.id,
    value,
    formattedValue: formatMetric(value, unit),
    unit,
  }
}

function dimensionValue(
  row: SnapshotRow,
  dimension: 'project' | 'task' | 'group',
): string {
  return {
    project: row.project_name,
    task: row.scene_name,
    group: row.group_name,
  }[dimension]
}

export function resolveOverviewMetric(
  card: DashboardMetricCard,
  rows: SnapshotRow[],
  catalog: AnalysisMetric[] = [],
): DashboardMetricResult {
  const total = emptyTotals()
  for (const row of rows) addRow(total, row)

  const values: DashboardMetricResult['values'] = {}
  const breakdowns: DashboardMetricResult['breakdowns'] = {}
  for (const block of card.blocks) {
    if (block.kind === 'metric-value') {
      values[block.id] = resolveValue(
        block.metric,
        total,
        catalog,
        block.label,
      )
      continue
    }
    if (block.kind !== 'breakdown') continue
    const grouped = new Map<string, ResultTotals>()
    for (const row of rows) {
      const label = dimensionValue(row, block.dimension)
      const group = grouped.get(label) ?? emptyTotals()
      addRow(group, row)
      grouped.set(label, group)
    }
    breakdowns[block.id] = [...grouped.entries()]
      .sort(([left], [right]) => left.localeCompare(right, 'zh-CN'))
      .slice(0, block.limit)
      .map(([label, group]) => ({
        label,
        values: block.metrics.map((metric) =>
          resolveValue(metric, group, catalog),
        ),
      }))
  }
  return { values, breakdowns }
}

function metricBlock(
  id: string,
  metricId: string,
  label: string,
  emphasis: 'primary' | 'supporting',
  width: 'full' | 'half' | 'third',
  color: string,
): DashboardMetricBlock {
  return {
    id,
    kind: 'metric-value',
    metric: { id: metricId },
    label,
    emphasis,
    width,
    style: {
      valueSize: emphasis === 'primary' ? 38 : 21,
      valueColor: color,
      labelSize: 10,
      labelColor: '#667085',
    },
  }
}

function breakdownBlock(
  id: string,
  metrics: string[],
): DashboardMetricBlock {
  return {
    id,
    kind: 'breakdown',
    dimension: 'project',
    metrics: metrics.map((metricId) => ({ id: metricId })),
    limit: 8,
    width: 'full',
  }
}

function cardStyle(accentColor: string, backgroundColor: string, textColor: string) {
  return {
    accentColor,
    backgroundColor,
    textColor,
    titleSize: 15,
    density: 'comfortable' as const,
  }
}

