function presetForLegacy(metricId: LegacyDashboardMetricId): DashboardMetricCard {
  const defaults = defaultOverviewCards()
  return cloneConfig(
    metricId === 'annotation_quality'
      ? defaults[0]!
      : metricId === 'acceptance_result'
        ? defaults[2]!
        : defaults[1]!,
  )
}

export function isOverviewCardV2(
  card: DashboardMetricCard | LegacyDashboardMetricCard,
): card is DashboardMetricCard {
  return 'blocks' in card && Array.isArray(card.blocks)
}

export function normalizeOverviewCard(
  card: DashboardMetricCard | LegacyDashboardMetricCard,
): DashboardMetricCard {
  if (isOverviewCardV2(card)) return cloneConfig(card)
  const migrated = presetForLegacy(card.metricId)
  migrated.id = card.id
  migrated.title = card.title
  migrated.description = card.description
  migrated.origin.type = 'user'
  migrated.action = { type: 'jump', targetCardId: card.jumpTarget }
  migrated.style = {
    accentColor: card.style.accentColor,
    backgroundColor: card.style.backgroundColor,
    textColor: card.style.textColor,
    titleSize: card.style.titleSize,
    density: card.style.density,
  }
  migrated.layout = {
    ...cloneConfig(card.layout),
    h: Math.max(5, card.layout.h),
    minH: Math.max(4, card.layout.minH),
  }
  const primary = migrated.blocks.find(
    (block) => block.kind === 'metric-value' && block.emphasis === 'primary',
  )
  if (primary?.kind === 'metric-value') {
    primary.style.valueSize = card.style.valueSize
  }
  if (!card.style.showProjectBreakdown) {
    migrated.blocks = migrated.blocks.filter((block) => block.kind !== 'breakdown')
  }
  return migrated
}

export function nextOverviewCard(
  metricId: LegacyDashboardMetricId,
): DashboardMetricCard {
  const card = presetForLegacy(metricId)
  card.id = `overview-${Date.now()}`
  card.origin = { type: 'user' }
  card.layout = { x: 0, y: 0, w: 4, h: 5, minW: 3, minH: 4 }
  return card
}

export function duplicateOverviewCard(
  card: DashboardMetricCard,
): DashboardMetricCard {
  const copy = cloneConfig(card)
  copy.id = `overview-${Date.now()}`
  copy.title = `${card.title}（副本）`
  copy.origin = { type: 'user' }
  copy.layout = {
    ...copy.layout,
    x: Math.min(11, copy.layout.x + 1),
    y: copy.layout.y + 1,
  }
  return copy
}

export function restoreOverviewPreset(
  card: DashboardMetricCard,
): DashboardMetricCard | null {
  const presetId = card.origin.presetId
  if (!presetId) return null
  const preset = defaultOverviewCards().find(
    (candidate) => candidate.origin.presetId === presetId,
  )
  if (!preset) return null
  return {
    ...cloneConfig(preset),
    id: card.id,
    layout: cloneConfig(card.layout),
  }
}

from __future__ import annotations

from typing import Any

from src.database import PGConnector
from .models import SnapshotFilter


METRIC_NUMBER_KEYS = (
    "annotation_total",
    "annotation_submitted",
    "expect_alloc",
    "actual_alloc",
    "actual_complete",
    "correct",
    "incorrect",
    "expect_pass",
    "expect_reject",
    "actual_pass",
    "actual_reject",
)


class SnapshotRepository:
    def __init__(self, postgres: PGConnector) -> None:
        self._postgres = postgres
        self._table = f"{postgres.schema}.t_qc_daily_snapshot"

    @staticmethod
    def _where(filters: SnapshotFilter) -> tuple[str, dict[str, Any]]:
        clauses: list[str] = []
        params: dict[str, Any] = {}
        for field in (
            "stat_date_start",
            "stat_date_end",
            "scene_name",
            "group_name",
            "employee_id",
            "project_name",
        ):
            value = getattr(filters, field)
            if value in (None, ""):
                continue
            if field == "stat_date_start":
                clauses.append("stat_date >= %(stat_date_start)s")
            elif field == "stat_date_end":
                clauses.append("stat_date <= %(stat_date_end)s")
            else:
                clauses.append(f"{field} = %({field})s")
            params[field] = value
        return (" WHERE " + " AND ".join(clauses)) if clauses else "", params

    @staticmethod
    def _sum_columns() -> str:
        columns = [
            "SUM(annotation_total)::integer AS annotation_total",
            "SUM(annotation_submitted)::integer AS annotation_submitted",
        ]
        for metric_column in ("good_metrics", "bad_metrics"):
            prefix = metric_column.removesuffix("_metrics")
            columns.extend(
                "SUM(COALESCE(NULLIF("
                f"{metric_column}->>'{key}', '')::integer, 0))::integer "
                f"AS {prefix}_{key}"
                for key in METRIC_NUMBER_KEYS
            )
        return ",\n".join(columns)

    def _aggregate(
        self,
        filters: SnapshotFilter,
        dimensions: tuple[str, ...],
    ) -> list[dict[str, Any]]:
        where_sql, params = self._where(filters)
        dimension_sql = ", ".join(dimensions)
        statement = f"""
            SELECT
                {dimension_sql},
                {self._sum_columns()},
                MAX(computed_at) AS computed_at
            FROM {self._table}
            {where_sql}
            GROUP BY {dimension_sql}
            ORDER BY {dimension_sql}
        """
        return self._postgres.fetch_all(statement, params)

    def aggregate_by_scene(self, filters: SnapshotFilter) -> list[dict[str, Any]]:
        return self._aggregate(
            filters,
            ("stat_date", "project_name", "scene_name"),
        )

    def aggregate_by_project(self, filters: SnapshotFilter) -> list[dict[str, Any]]:
        return self._aggregate(filters, ("stat_date", "project_name"))

    def aggregate_by_group(self, filters: SnapshotFilter) -> list[dict[str, Any]]:
        return self._aggregate(
            filters,
            ("stat_date", "project_name", "scene_name", "group_name"),
        )

    def aggregate_by_employee(self, filters: SnapshotFilter) -> list[dict[str, Any]]:
        return self._aggregate(
            filters,
            (
                "stat_date",
                "project_name",
                "scene_name",
                "group_name",
                "employee_id",
            ),
        )

    def list_minimum_rows(
        self,
        filters: SnapshotFilter,
        *,
        limit: int = 200,
        offset: int = 0,
    ) -> list[dict[str, Any]]:
        where_sql, params = self._where(filters)
        params.update({"limit": limit, "offset": offset})
        statement = f"""
            SELECT *
            FROM {self._table}
            {where_sql}
            ORDER BY stat_date DESC, project_name, scene_name, group_name, employee_id
            LIMIT %(limit)s OFFSET %(offset)s
        """
        return self._postgres.fetch_all(statement, params)

    # Kept as an explicit alias for existing callers while the source-aligned
    # name becomes the public contract.
    list_rows = list_minimum_rows

    def count_rows(self, filters: SnapshotFilter) -> int:
        where_sql, params = self._where(filters)
        row = self._postgres.fetch_one(
            f"SELECT COUNT(*)::integer AS count FROM {self._table}{where_sql}",
            params,
        )
        return int(row["count"]) if row else 0

import { computed, onMounted, reactive, readonly, shallowRef } from 'vue'
import axios from 'axios'
import {
  getEmployeeAggregate,
  getGroupAggregate,
  getProjectAggregate,
  getSceneAggregate,
  getSnapshotRows,
} from '../api/snapshot'
import type {
  AggregateLevel,
  AggregateNode,
  EmployeeAggregate,
  GroupAggregate,
  ProjectAggregate,
  SceneAggregate,
  SnapshotQuery,
  SnapshotRow,
} from '../types/snapshot'

function formatLocalDate(value: Date): string {
  const year = value.getFullYear()
  const month = String(value.getMonth() + 1).padStart(2, '0')
  const day = String(value.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function defaultQuery(): Required<Pick<SnapshotQuery, 'stat_date_start' | 'stat_date_end'>> &
  SnapshotQuery {
  const today = new Date()
  const thirteenDaysAgo = new Date(today)
  thirteenDaysAgo.setDate(thirteenDaysAgo.getDate() - 13)
  return {
    stat_date_start: formatLocalDate(thirteenDaysAgo),
    stat_date_end: formatLocalDate(today),
    project_name: '',
    scene_name: '',
    group_name: '',
    employee_id: '',
  }
}

function toNode(
  value: ProjectAggregate | SceneAggregate | GroupAggregate | EmployeeAggregate,
  level: AggregateLevel,
): AggregateNode {
  const sceneName = 'scene_name' in value ? value.scene_name : ''
  const groupName = 'group_name' in value ? value.group_name : ''
  const employeeId = 'employee_id' in value ? value.employee_id : ''
  const id = [
    level,
    value.stat_date,
    value.project_name,
    sceneName,
    groupName,
    employeeId,
  ]
    .filter(Boolean)
    .join(':')
  return {
    id,
    level,
    stat_date: value.stat_date,
    project_name: value.project_name,
    scene_name: sceneName,
    group_name: groupName,
    employee_id: employeeId,
    computed_at: value.computed_at,
    annotation_total: value.annotation_total,
    annotation_submitted: value.annotation_submitted,
    good_metrics: structuredClone(value.good_metrics),
    bad_metrics: structuredClone(value.bad_metrics),
    hasChildren: level !== 'employee',
    ...(level === 'employee' ? {} : { children: [] }),
  }
}

function errorMessage(error: unknown): string {
  if (axios.isAxiosError(error)) {
    const detail = error.response?.data?.detail
    if (typeof detail === 'string') return detail
    if (error.code === 'ECONNABORTED') return '后端请求超时，请检查本地服务。'
    if (!error.response) return '无法连接本地后端，请确认 FastAPI 已启动。'
    return `后端返回 ${error.response.status}，请检查接口日志。`
  }
  return error instanceof Error ? error.message : '发生未知错误。'
}

export function useSnapshotExplorer() {
  const query = reactive<SnapshotQuery>(defaultQuery())
  const loading = shallowRef(false)
  const error = shallowRef('')
  const notice = shallowRef('')
  const sceneRows = shallowRef<SceneAggregate[]>([])
  const snapshotRows = shallowRef<SnapshotRow[]>([])
  const tree = shallowRef<AggregateNode[]>([])
  const loadedKeys = shallowRef<Set<string>>(new Set())
  const loadingKeys = shallowRef<Set<string>>(new Set())
  const computedAt = shallowRef<string | null>(null)

  const projectOptions = computed(() =>
    [...new Set(sceneRows.value.map((row) => row.project_name))].sort(),
  )

  const sceneOptions = computed(() =>
    [...new Set(sceneRows.value.map((row) => row.scene_name))].sort(),
  )

  const filtersSummary = computed(() => {
    const parts = [
      query.stat_date_start ? `${query.stat_date_start} 起` : '',
      query.stat_date_end ? `${query.stat_date_end} 止` : '',
      query.project_name ? `项目：${query.project_name}` : '',
      query.scene_name ? `标注任务：${query.scene_name}` : '',
      query.group_name ? `组：${query.group_name}` : '',
      query.employee_id ? `标注员：${query.employee_id}` : '',
    ].filter(Boolean)
    return parts.join(' · ') || '全部实验数据'
  })

  function apiQuery(): SnapshotQuery {
    return Object.fromEntries(
      Object.entries(query).filter(([, value]) => value !== '' && value != null),
    )
  }

  function updateNode(id: string, update: (node: AggregateNode) => void) {
    function visit(nodes: AggregateNode[]): boolean {
      for (const node of nodes) {
        if (node.id === id) {
          update(node)
          return true
        }
        if (node.children && visit(node.children)) return true
      }
      return false
    }

    const next = structuredClone(tree.value)
    if (visit(next)) tree.value = next
  }

  async function load() {
    loading.value = true
    error.value = ''
    notice.value = ''
    loadedKeys.value = new Set()
    loadingKeys.value = new Set()
    try {
      const [projectResponse, sceneResponse, rowResponse] = await Promise.all([
        getProjectAggregate(apiQuery()),
        getSceneAggregate(apiQuery()),
        getSnapshotRows(apiQuery()),
      ])
      sceneRows.value = sceneResponse.items
      snapshotRows.value = rowResponse.items
      tree.value = projectResponse.items.map((item) => toNode(item, 'project'))
      computedAt.value =
        [projectResponse.computed_at, sceneResponse.computed_at]
          .filter((value): value is string => Boolean(value))
          .sort()
          .at(-1) ?? null
      notice.value = sceneResponse.total
        ? `已加载 ${projectResponse.total} 条日期—项目、${sceneResponse.total} 条日期—标注任务聚合。可按项目继续下钻到任务、组和员工。`
        : '接口返回成功，但当前筛选范围没有快照数据。'
    } catch (caught) {
      error.value = errorMessage(caught)
      sceneRows.value = []
      snapshotRows.value = []
      tree.value = []
      computedAt.value = null
    } finally {
      loading.value = false
    }
  }

  async function expand(node: AggregateNode): Promise<boolean> {
    if (
      node.level === 'employee' ||
      loadedKeys.value.has(node.id) ||
      loadingKeys.value.has(node.id)
    ) {
      return Boolean(node.children?.length)
    }

    loadingKeys.value = new Set([...loadingKeys.value, node.id])
    updateNode(node.id, (current) => {
      current.loading = true
    })
    error.value = ''

    try {
      let children: AggregateNode[]
      if (node.level === 'project') {
        const response = await getSceneAggregate({
          ...apiQuery(),
          stat_date_start: node.stat_date,
          stat_date_end: node.stat_date,
          project_name: node.project_name,
        })
        children = response.items.map((item) => toNode(item, 'scene'))
      } else if (node.level === 'scene') {
        const response = await getGroupAggregate({
          ...apiQuery(),
          stat_date_start: node.stat_date,
          stat_date_end: node.stat_date,
          project_name: node.project_name,
          scene_name: node.scene_name,
        })
        children = response.items.map((item) => toNode(item, 'group'))
      } else {
        const response = await getEmployeeAggregate({
          ...apiQuery(),
          stat_date_start: node.stat_date,
          stat_date_end: node.stat_date,
          project_name: node.project_name,
          scene_name: node.scene_name,
          group_name: node.group_name,
        })
        children = response.items.map((item) => toNode(item, 'employee'))
      }

      updateNode(node.id, (current) => {
        current.children = children
        current.hasChildren = children.length > 0
        current.loading = false
      })
      loadedKeys.value = new Set([...loadedKeys.value, node.id])
      return children.length > 0
    } catch (caught) {
      updateNode(node.id, (current) => {
        current.loading = false
      })
      error.value = `“${node.project_name}${node.scene_name ? ` / ${node.scene_name}` : ''}${node.group_name ? ` / ${node.group_name}` : ''}”下层数据加载失败：${errorMessage(caught)}`
      return false
    } finally {
      const nextLoading = new Set(loadingKeys.value)
      nextLoading.delete(node.id)
      loadingKeys.value = nextLoading
    }
  }

  function reset() {
    Object.assign(query, defaultQuery())
  }

  async function resetAndLoad() {
    reset()
    await load()
  }

  onMounted(load)

  return {
    query,
    loading: readonly(loading),
    error: readonly(error),
    notice: readonly(notice),
    sceneRows: readonly(sceneRows),
    snapshotRows: readonly(snapshotRows),
    tree: readonly(tree),
    loadingKeys: readonly(loadingKeys),
    computedAt: readonly(computedAt),
    sceneOptions,
    projectOptions,
    filtersSummary,
    load,
    expand,
    resetAndLoad,
  }
}

