import { http } from '@/shared/api/http'
import type {
  DataResponse,
  EmployeeAggregate,
  GroupAggregate,
  ProjectAggregate,
  SceneAggregate,
  SnapshotRow,
  SnapshotQuery,
} from '../types/snapshot'

const SNAPSHOT_PAGE_SIZE = 1000
const SNAPSHOT_BROWSER_LIMIT = 10_000

export async function getProjectAggregate(
  query: SnapshotQuery,
): Promise<DataResponse<ProjectAggregate>> {
  const response = await http.get<DataResponse<ProjectAggregate>>(
    '/snapshots/aggregate/project',
    { params: query },
  )
  return response.data
}

export async function getSceneAggregate(
  query: SnapshotQuery,
): Promise<DataResponse<SceneAggregate>> {
  const response = await http.get<DataResponse<SceneAggregate>>(
    '/snapshots/aggregate/scene',
    { params: query },
  )
  return response.data
}

export async function getGroupAggregate(
  query: SnapshotQuery & { scene_name: string },
): Promise<DataResponse<GroupAggregate>> {
  const response = await http.get<DataResponse<GroupAggregate>>(
    '/snapshots/aggregate/group',
    { params: query },
  )
  return response.data
}

export async function getEmployeeAggregate(
  query: SnapshotQuery & { scene_name: string; group_name: string },
): Promise<DataResponse<EmployeeAggregate>> {
  const response = await http.get<DataResponse<EmployeeAggregate>>(
    '/snapshots/aggregate/employee',
    { params: query },
  )
  return response.data
}

export async function getSnapshotRows(
  query: SnapshotQuery,
): Promise<DataResponse<SnapshotRow>> {
  const first = await http.get<DataResponse<SnapshotRow>>(
    '/snapshots/rows',
    { params: { ...query, limit: SNAPSHOT_PAGE_SIZE, offset: 0 } },
  )
  if (first.data.total > SNAPSHOT_BROWSER_LIMIT) {
    throw new Error(
      `当前范围命中 ${first.data.total} 行，超过浏览器端临时兼容上限 ${SNAPSHOT_BROWSER_LIMIT} 行；请缩小顶部范围。`,
    )
  }
  if (first.data.items.length >= first.data.total) return first.data

  // V1 总览和统计卡片仍在浏览器聚合快照行。这里分页取齐是规模种子的
  // 正确性兼容层；总览/图表 V2 应改用受控后端聚合后删除这段分页。
  const offsets = Array.from(
    {
      length: Math.ceil(first.data.total / SNAPSHOT_PAGE_SIZE) - 1,
    },
    (_, index) => (index + 1) * SNAPSHOT_PAGE_SIZE,
  )
  const pages = await Promise.all(
    offsets.map((offset) =>
      http.get<DataResponse<SnapshotRow>>('/snapshots/rows', {
        params: { ...query, limit: SNAPSHOT_PAGE_SIZE, offset },
      }),
    ),
  )
  const responses = [first.data, ...pages.map((response) => response.data)]
  return {
    ...first.data,
    items: responses.flatMap((response) => response.items),
    computed_at:
      responses
        .map((response) => response.computed_at)
        .filter((value): value is string => Boolean(value))
        .sort()
        .at(-1) ?? null,
  }
}

import { readonly, shallowRef, watch } from 'vue'
import axios from 'axios'
import type { SnapshotQuery } from '../../types/snapshot'
import { postAnalysisQuery } from '../api/analysis'
import {
  metricReferenceKey,
  toTaskAnalysisNodes,
} from '../utils'
import type {
  AnalysisMetricReference,
  AnalysisScope,
  TaskAnalysisLevel,
  TaskAnalysisPath,
  TaskAnalysisRow,
} from '../types/analysis'

const SOURCE_ID = 'manual_qc.snapshot.v20260709'

export const TASK_TABLE_BASE_MEASURES: AnalysisMetricReference[] = [
  { id: 'annotation.submitted' },
  { id: 'annotation.good_rate' },
  { id: 'acceptance.allocated' },
  { id: 'acceptance.allocation_coverage_rate' },
  { id: 'acceptance.completed' },
  { id: 'acceptance.completion_rate' },
  { id: 'acceptance.pass_rate' },
]

function errorMessage(error: unknown): string {
  if (axios.isAxiosError(error)) {
    const detail = error.response?.data?.detail
    if (typeof detail === 'string') return detail
    if (!error.response) return '无法连接人工质检分析接口，请确认 FastAPI 已启动。'
    return `人工质检分析接口返回 ${error.response.status}。`
  }
  return error instanceof Error ? error.message : '任务明细读取失败。'
}

function nextLevel(level: TaskAnalysisLevel): TaskAnalysisLevel | null {
  return {
    task: 'date',
    date: 'group',
    group: 'employee',
    employee: null,
  }[level] as TaskAnalysisLevel | null
}

function groupBy(level: TaskAnalysisLevel): string[] {
  return level === 'task' ? ['project', 'task'] : [level]
}

function replaceChildren(
  rows: TaskAnalysisRow[],
  rowId: string,
  children: TaskAnalysisRow[],
): TaskAnalysisRow[] {
  return rows.map((row) => {
    if (row.id === rowId) return { ...row, children }
    if (!row.children?.length) return row
    return {
      ...row,
      children: replaceChildren(row.children, rowId, children),
    }
  })
}

export function useTaskAnalysisTree(pageQuery: SnapshotQuery) {
  const rows = shallowRef<TaskAnalysisRow[]>([])
  const loading = shallowRef(false)
  const error = shallowRef('')
  const computedAt = shallowRef<string | null>(null)
  const total = shallowRef(0)
  const loadingRowIds = shallowRef<Set<string>>(new Set())
  const pinnedMetrics = shallowRef<AnalysisMetricReference[]>([])
  let rootRequestId = 0

  function baseScope(): AnalysisScope {
    return {
      dateStart: pageQuery.stat_date_start || undefined,
      dateEnd: pageQuery.stat_date_end || undefined,
      projectNames: pageQuery.project_name ? [pageQuery.project_name] : [],
      taskNames: pageQuery.scene_name ? [pageQuery.scene_name] : [],
      groupNames: pageQuery.group_name ? [pageQuery.group_name] : [],
      employeeIds: pageQuery.employee_id ? [pageQuery.employee_id] : [],
    }
  }

  function pathScope(path: TaskAnalysisPath): AnalysisScope {
    const scope = baseScope()
    scope.projectNames = [path.project]
    scope.taskNames = [path.task]
    if (path.date) {
      scope.dateStart = path.date
      scope.dateEnd = path.date
    }
    if (path.group) scope.groupNames = [path.group]
    if (path.employee) scope.employeeIds = [path.employee]
    return scope
  }

  function measures(): AnalysisMetricReference[] {
    const unique = new Map<string, AnalysisMetricReference>()
    for (const reference of [
      ...TASK_TABLE_BASE_MEASURES,
      ...pinnedMetrics.value,
    ]) {
      unique.set(metricReferenceKey(reference), reference)
    }
    return [...unique.values()]
  }

  async function queryLevel(
    level: TaskAnalysisLevel,
    scope: AnalysisScope,
    parent?: TaskAnalysisPath,
  ): Promise<{
    rows: TaskAnalysisRow[]
    total: number
    computedAt: string | null
  }> {
    const result = await postAnalysisQuery({
      sourceId: SOURCE_ID,
      scope,
      groupBy: groupBy(level),
      measures: measures(),
      sort: level === 'task'
        ? [
            {
              target: { id: 'annotation.submitted' },
              direction: 'descending',
            },
          ]
        : [
            {
              target: { id: level },
              direction: 'ascending',
            },
          ],
      page: { number: 1, size: 200 },
    })
    return {
      rows: toTaskAnalysisNodes(result.rows, {
        level,
        parent,
        pinnedMetrics: pinnedMetrics.value,
      }),
      total: result.total,
      computedAt: result.computedAt,
    }
  }

  async function load(): Promise<void> {
    const requestId = ++rootRequestId
    loading.value = true
    error.value = ''
    try {
      const result = await queryLevel('task', baseScope())
      if (requestId !== rootRequestId) return
      rows.value = result.rows
      total.value = result.total
      computedAt.value = result.computedAt
    } catch (caught) {
      if (requestId !== rootRequestId) return
      rows.value = []
      total.value = 0
      computedAt.value = null
      error.value = errorMessage(caught)
    } finally {
      if (requestId === rootRequestId) loading.value = false
    }
  }

  async function loadChildren(row: TaskAnalysisRow): Promise<boolean> {
    const level = nextLevel(row.level)
    if (!level || loadingRowIds.value.has(row.id)) return false
    if (row.children?.length) return true

    loadingRowIds.value = new Set([...loadingRowIds.value, row.id])
    error.value = ''
    try {
      const result = await queryLevel(level, pathScope(row.path), row.path)
      rows.value = replaceChildren(rows.value, row.id, result.rows)
      return result.rows.length > 0
    } catch (caught) {
      error.value = `“${row.objectLabel}”下层数据读取失败：${errorMessage(caught)}`
      return false
    } finally {
      const next = new Set(loadingRowIds.value)
      next.delete(row.id)
      loadingRowIds.value = next
    }
  }

  async function setPinnedMetrics(
    references: AnalysisMetricReference[],
  ): Promise<void> {
    pinnedMetrics.value = references.slice(0, 5)
    await load()
  }

  watch(
    () => [
      pageQuery.stat_date_start,
      pageQuery.stat_date_end,
      pageQuery.project_name,
      pageQuery.scene_name,
      pageQuery.group_name,
      pageQuery.employee_id,
    ],
    () => void load(),
    { immediate: true },
  )

  return {
    rows: readonly(rows),
    loading: readonly(loading),
    error: readonly(error),
    computedAt: readonly(computedAt),
    total: readonly(total),
    pinnedMetrics: readonly(pinnedMetrics),
    loadingRowIds: readonly(loadingRowIds),
    load,
    loadChildren,
    setPinnedMetrics,
  }
}

from __future__ import annotations

from typing import Any

from .catalog import SOURCE_ID, catalog_payload, get_dimension, get_metric
from .models import (
    AnalysisFilter,
    AnalysisQuery,
    AnalysisResult,
    AnalysisScope,
    MetricReference,
)
from .repository import AnalysisRepository


class AnalysisValidationError(ValueError):
    """A user-correctable controlled-analysis request error."""


class AnalysisQueryService:
    """Validate business identifiers before the repository builds SQL."""

    def __init__(self, repository: AnalysisRepository) -> None:
        self._repository = repository

    @staticmethod
    def catalog() -> dict[str, object]:
        return catalog_payload()

    def query(self, query: AnalysisQuery) -> AnalysisResult:
        self._validate(query)
        rows, total = self._repository.query(query)
        latest = max((row.computed_at for row in rows), default=None)
        return AnalysisResult(
            source_id=query.source_id,
            group_by=query.group_by,
            rows=rows,
            total=total,
            page=query.page,
            computed_at=latest,
        )

    def facets(
        self,
        *,
        source_id: str,
        scope: AnalysisScope,
        dimension_id: str,
        question_label: str | None,
    ) -> list[str]:
        if source_id != SOURCE_ID:
            raise AnalysisValidationError(f"未知分析数据源：{source_id}")
        allowed = {
            "project",
            "task",
            "group",
            "employee",
            "question_label",
            "question_option",
        }
        if dimension_id not in allowed:
            raise AnalysisValidationError(f"不支持的候选值维度：{dimension_id}")
        if dimension_id == "question_option" and not question_label:
            raise AnalysisValidationError("读取问题选项前必须指定问题标签")
        if scope.date_start and scope.date_end and scope.date_start > scope.date_end:
            raise AnalysisValidationError("开始日期不能晚于结束日期")
        return self._repository.facets(
            scope=scope,
            dimension_id=dimension_id,
            question_label=question_label,
        )

    def _validate(self, query: AnalysisQuery) -> None:
        if query.source_id != SOURCE_ID:
            raise AnalysisValidationError(f"未知分析数据源：{query.source_id}")
        if query.scope.date_start and query.scope.date_end:
            if query.scope.date_start > query.scope.date_end:
                raise AnalysisValidationError("开始日期不能晚于结束日期")
        if not 1 <= len(query.group_by) <= 3:
            raise AnalysisValidationError("一次查询必须按 1 到 3 个维度分组")
        if len(set(query.group_by)) != len(query.group_by):
            raise AnalysisValidationError("分组维度不能重复")
        for identifier in query.group_by:
            if get_dimension(identifier) is None:
                raise AnalysisValidationError(f"不支持的分组维度：{identifier}")
        if not 1 <= len(query.measures) <= 12:
            raise AnalysisValidationError("一次查询必须选择 1 到 12 个指标")
        if len({item.stable_key() for item in query.measures}) != len(query.measures):
            raise AnalysisValidationError("同一指标不能重复选择")
        if len(query.filters) > 12:
            raise AnalysisValidationError("一次查询最多使用 12 个筛选条件")
        if len(query.sort) > 3:
            raise AnalysisValidationError("一次查询最多使用 3 个排序条件")
        if not 1 <= query.page.number <= 10_000:
            raise AnalysisValidationError("页码超出允许范围")
        if not 1 <= query.page.size <= 200:
            raise AnalysisValidationError("每页最多返回 200 行")

        for reference in query.measures:
            self._validate_reference(reference)
        for item in query.filters:
            self._validate_filter(item)
        for item in query.sort:
            self._validate_reference(item.target, allow_dimension=True)
            if item.direction not in {"ascending", "descending"}:
                raise AnalysisValidationError("排序方向只能是 ascending 或 descending")
            if get_dimension(item.target.id) is not None and item.target.id not in query.group_by:
                raise AnalysisValidationError("只能按当前分组结果中的维度排序")

    def _validate_reference(
        self,
        reference: MetricReference,
        *,
        allow_dimension: bool = False,
    ) -> None:
        dimension = get_dimension(reference.id)
        if dimension is not None:
            if allow_dimension:
                return
            raise AnalysisValidationError(f"{dimension.label} 是维度，不能作为统计指标")
        metric = get_metric(reference.id)
        if metric is None:
            raise AnalysisValidationError(f"未知统计指标：{reference.id}")
        if metric.requires_question_option:
            required = {"question_label", "question_option"}
            actual = set(reference.parameters)
            if actual != required or not all(reference.parameters.values()):
                raise AnalysisValidationError(
                    f"指标“{metric.label}”必须指定问题标签和问题选项"
                )
        elif reference.parameters:
            raise AnalysisValidationError(f"指标“{metric.label}”不接受附加参数")

    def _validate_filter(self, item: AnalysisFilter) -> None:
        dimension = get_dimension(item.target.id)
        if dimension is not None:
            if item.operator not in dimension.filter_operators:
                raise AnalysisValidationError(
                    f"维度“{dimension.label}”不支持 {item.operator} 筛选"
                )
            self._validate_filter_value(item.operator, item.value)
            return
        self._validate_reference(item.target)
        metric = get_metric(item.target.id)
        assert metric is not None
        if item.operator not in metric.filter_operators:
            raise AnalysisValidationError(
                f"指标“{metric.label}”不支持 {item.operator} 筛选"
            )
        self._validate_filter_value(item.operator, item.value)

    @staticmethod
    def _validate_filter_value(operator: str, value: Any) -> None:
        if operator == "in":
            if not isinstance(value, (list, tuple)) or not value:
                raise AnalysisValidationError("in 筛选需要至少一个值")
            return
        if operator == "between":
            if (
                not isinstance(value, (list, tuple))
                or len(value) != 2
                or value[0] is None
                or value[1] is None
            ):
                raise AnalysisValidationError("between 筛选需要两个边界值")
            return
        if value is None or value == "":
            raise AnalysisValidationError("筛选条件不能为空")

