    },
    axes: value.axes ?? [countAxis(), rateAxis()],
    layers: value.layers,
    presentation: {
      showLegend: true,
      legendPosition: 'top',
      categorySort:
        value.categoryDimension === 'question-option'
          ? 'value-desc'
          : 'natural',
      categoryLimit:
        value.categoryDimension === 'question-option' ? 12 : 24,
      orientation: value.orientation ?? 'vertical',
      fontScale: 'medium',
    },
    layout: value.layout,
  }
}

